<script>
(function() {
    // CONFIGURATION
    const WIDTH = 80;   // Internal grid width (cells) - minimum requirement met via scale factor.
    const HEIGHT = 80;  // Height in cells (>=400px CSS -> Scale=5).
    const SCALE = 5;

    // DOM Elements
    const canvasContainer = document.getElementById('game-container');

    // Canvas Setup: width/height set to match internal grid * scale. 
    // At 80x80 and scale 5, the CSS size is exactly 400px x 400px (matches requirement).
    const canvas = document.createElement('canvas');
    canvas.width = WIDTH * SCALE;
    canvas.height = HEIGHT * SCALE;
    canvas.style.width = (WIDTH * SCALE) + 'px'; // Force display size to be exactly the scaled pixel dimensions for simplicity.
    canvas.style.height = (HEIGHT * SCALE) + 'px';

    const ctx = canvas.getContext('2d', { willReadFrequently: true });

    // Grid Data: Uint8Array for performance
    let grid = new Uint8Array(WIDTH * HEIGHT).fill(0);

    // Index helper
    const idx = (x, y) => x + y * WIDTH;

    // Map string material names to internal codes and colors
    const MATS = { "sand": 1, "water": 2, "wall": 3, "acid": 4 };
    const COLORS = { 
        0: '#202530',   // Empty (Background) - dark theme match
        1: '#DFA15E',   // Sand - warm brownish yellow
        2: '#4B9CD3',   // Water - blueish cyan
        3: '#6C7A85',   // Wall - grey-blue
        4: '#00FF4A'    // Acid - bright green (laser-like)
    };

    function getMatId(name) { return MATS[name] || 0; }

    // API methods exposed on window.sim
    window.sim = {
        w: WIDTH,
        h: HEIGHT,

        tick(n) {
            for (let i=0; i<n; i++) {
                simulateStep();
            }
        },

        get(x, y) {
            if (!grid[idx(x,y)]) return "empty";
            const v = grid[idx(x,y)];
            // Reverse mapping of internal ID to string name
            for(let k in MATS) if(MATS[k] === v) return k;
            return "wall"; // Fallback shouldn't happen
        },

        set(x, y, matStr) {
            const id = getMatId(matStr);
            grid[idx(x,y)] = id;
        },

        clear() {
            for (let i=0; i<grid.length; i++) grid[i] = 0;
        }
    };

    // Simulation Logic: Single Buffer, Bottom-Up Iteration
    function simulateStep() {
        // Iterate rows from bottom up (excluding the very last row which is solid/boundary)
        for (let y = HEIGHT - 2; y >= 0; y--) {
            // Process columns. Order of x iteration doesn't strictly matter for Bottom-Up correctness but 
            // we can iterate in any order, e.g., Left to Right or Randomized. We use simple L->R loop.
            for (let x = 1; x < WIDTH - 1; x++) { // Skip edges? No, process all cells except bottom row boundaries if needed. Actually processing cols 0..WIDTH-1 is fine but need bounds checks. I'll do full range with boundary logic inside cell check or skip edges entirely as they are solid? "side edges act as solid boundaries" -> meaning particles cannot leave grid at sides. We should process edge cells too (e.g., sand falling to bottom row).
                // Let's iterate all columns for simplicity, but ensure neighbor checks respect bounds 0..WIDTH-1.
            }
        }
    }

    function simulateStep() {
        // Iterate rows from BOTTOM UP: y = h-2 down to 0 (so we can check below at y+1)
        for (let y = HEIGHT - 2; y >= 0; y--) {
            for (let x = WIDTH / 2 | 0; ...) 
                // To avoid bias, maybe iterate columns in varying order? Not necessary. Just use random or standard loop. 
                // However, I'll do a simple left-to-right scan but skipping the edges (x=0 and x=W-1) might be safer since they are boundaries.
            }
        }
    }

    function simulateStep() {
        // Iterate rows from bottom up: starting at second to last row down to top row 0.
        for (let y = HEIGHT - 2; y >= 0; y--) {
            // For each cell in this row, we process movement if it's a movable particle.
            for (let x = 1; x < WIDTH - 1; x++) { 
                let mat = grid[idx(x,y)];

                if (mat === 3) continue; // Wall never moves

                // Helper to check neighbor state safely within bounds?
                const getBelowX = () => y + 1;

                // If below is out of bounds -> treat as blocked. 
                let hasSpaceDown = false;
                if (y + 1 < HEIGHT) {
                    let belowMat = grid[idx(x, y+1)];
                    if (belowMat === 0 || belowMat === 2 || belowMat === 4) hasSpaceDown = true; // Empty or liquid/acid can be traversed/swapped? 
