                }

                switch (mat) {
                    case 1: // SAND
                        let belowIsWaterOrAcid = false;
                        if (y + 1 < HEIGHT) {
                            let bm = grid[idx(x,y+1)];
                            if (bm === 2 || bm === 4) belowIsWaterOrAcid = true;
                            else if (bm === 0) hasSpaceDown = true; // Empty space
                        }

                        if ((y + 1 < HEIGHT && grid[idx(x, y+1)] === 0)) {
                            // Move down to empty
