                            // Swap with water/acid: sand sinks, liquid rises.
                            // Since we process bottom-up, the cell below has already been processed for movement this tick? 
                            // Actually no, because row y+1 is done before row y starts in loop order (y decreasing). So its state reflects result of previous moves or initial static if blocked.
                            let targetIdx = idx(x,y+1);
                            grid[targetIdx] = 1;
                            grid[idx(x,y)] = grid[targetIdx]; // Put water/acid where sand was? No, we need to know which liquid it was originally, but in this frame the new state is what matters. Wait:
                            // If below cell contained Water (ID=2) at START of tick. Then `grid[targetIdx]` currently holds 2 (unless changed by its own move logic). 
                            // We want Sand to end up there, and Water/Acid to end up here.
                            let liquidType = grid[idx(x,y+1)];
                            if (liquidType === 0) { hasSpaceDown=true; } // Fallback? No.

                            // Actually simpler: Swap contents. But careful with re-ordering writes in single buffer.
                            grid[targetIdx] = 1;
                            grid[idx(x,y)] = liquidType; 
