                                let bmL = grid[idx(x-1,y+1)];
                                // Allow moving into empty or liquid? "slides diagonally down-left/down-right" implies finding a spot. Usually slides to empty cell below diagonal, not over another particle unless it's same type stacking allowed. Sand usually falls through water but doesn't slide *onto* sand? It rests on top of stack?
                                // Prompt: "If blocked below, it slides diagonally down-left/down-right (randomize the direction checked first). Otherwise it rests."
                                // Usually means moves to empty cell in that diagonal spot. Let's assume same as Sand falling into Empty OR swapping with Water/Acid at diagonal position.
                                if (bmL === 0 || bmL === 2 || bmL === 4) canMoveL = true;
                            }
                            if (y+1 < HEIGHT && x+1 < WIDTH) {
                                let bmR = grid[idx(x+1,y+1)];
                                if (bmR === 0 || bmR === 2 || bmR === 4) canMoveR = true;
                            }

                            // Randomize direction: flip coin.
