                        let canFallAcid = false;
                        if (y + 1 < HEIGHT && grid[idx(x,y+1)] === 0) {
                            canFallAcid = true;
                        }

                        if (canFallAcid) {
                            let targetIdx = idx(x,y+1);
                            // Check for reaction before moving? Or just move and then maybe react later. 
                            grid[targetIdx] = 4;
                            grid[idx(x,y)] = 0;
                        } else {
                            // Spread horizontally like water (if blocked below) AND dissolve neighbors.
                            let canSpreadL = false, canSpreadR = false;
                            if (x - 1 >= 0 && grid[idx(x-1, y)] === 0) canSpreadL = true;
                            if (x + 1 < WIDTH && grid[idx(x+1, y)] === 0) canSpreadR = true;

                            // Reaction Logic: Acid dissolves sand or wall cells it touches below or beside.
                            // "below" -> `(y+1)` neighbor? Or current row neighbors? Prompt says "touches below or beside". 
                            // Below means `grid[idx(x,y+1)]` (in case acid stays put). Beside means side neighbors.

                            let dissolved = false;

                            if (!dissolved) {
                                // Check sides in same row: x-1, x+1 for Sand/Wall
                                if (x - 1 >= 0 && grid[idx(x-1,y)] === 3 || grid[idx(x-1,y)] === 1) {
                                    // Dissolve neighbor sand/wall. Prompt says both may disappear or just target. I choose: acid stays, wall disappears -> "walls must erode". Wait prompt allows choice. To ensure erosion and avoid infinite loops of solid blocks staying while acids burn out, let's dissolve the adjacent block into empty (and maybe consume this acid? Let's keep it simple: Acid moves if blocked; also eats neighbors). 
                                    // I'll make neighbor become Empty immediately regardless of movement outcome.
                                    grid[idx(x-1,y)] = 0;
                                }
                            }
                            if (!dissolved) {
                                if (x + 1 < WIDTH && grid[idx(x+1,y)] === 3 || grid[idx(x+1,y)] === 1) {
                                    grid[idx(x+1,y)] = 0;
                                }
                            }
                             // Check below neighbor `(y+1)` for dissolution? Acid may be sitting on a block. If `grid[y+1][x]` is Sand/Wall -> dissolve it? 
                             if (!dissolved && y + 1 < HEIGHT) {
                                 let bm = grid[idx(x,y+1)];
                                 if (bm === 3 || bm === 1) {
                                     // Acid sits on top of Wall/Sand, dissolves it. But acid stays above? Or falls through? 
                                     // Usually acid eats what is below or beside. Let's dissolve the block below too.
                                     grid[idx(x,y+1)] = 0;
                                 }
                             }

                            if (canSpreadL || canSpreadR) {
                                let dir = Math.random() < 0.5 ? 'L' : 'R';
                                // Note: The spreading logic might be blocked now because we just dissolved a neighbor, but that cell is likely still occupied by the acid's new state? No, if acid moves into empty spot `x-1`, it sets there to Acid and clears current. That works fine.
                                if (dir === 'L' && canSpreadL) {
                                    let targetIdx = idx(x-1,y);
                                    grid[targetIdx] = 4;
                                    grid[idx(x,y)] = 0;
                                } else if (canSpreadR) {
                                    let targetIdx = idx(x+1,y);
                                    grid[targetIdx] = 4;
                                    grid[idx(x,y)] = 0;
                                }
                            }
                        }

                    default: // Empty or Wall -> do nothing
                }
            }
        }
    }

    // Render Loop (requestAnimationFrame)
    function render() {
        ctx.fillStyle = COLORS[0];
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        for (let y=0; y<HEIGHT; y++) {
            for (let x=0; x<WIDTH; x++) {
                const m = grid[idx(x,y)];
                if (m !== 0) {
                    ctx.fillStyle = COLORS[m] || '#fff'; // Fallback white
                    ctx.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
                }
            }
        }

        requestAnimationFrame(render);
    }

    render();

    // INPUT HANDLING: Mouse painting on canvas
    let isMouseDown = false;
    let currentMat = 'sand'; // default from UI button

    function paint(e) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((e.clientX - rect.left) / SCALE);
        const y = Math.floor((e.clientY - rect.top) / SCALE);

        if (x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT) {
            window.sim.set(x, y, currentMat);
        }
    }

    canvas.addEventListener('mousedown', () => isMouseDown = true; paint(event));
    canvas.addEventListener('mouseup', () => isMouseDown = false);
    canvas.addEventListener('mousemove', (e) => { if(isMouseDown) paint(e); });

    // UI: Material Buttons Selection
    const matBtns = document.querySelectorAll('.mat-btn');

    function updateActiveButton(matStr, btnElement) {
        for(let b of matBtns) b.classList.remove('active');
        if(btnElement) btnElement.classList.add('active');
    }

