    matBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            currentMat = btn.getAttribute('data-mat');
            updateActiveButton(currentMat, btn);
        });
    });

    // Clear button logic
    const clearBtn = document.getElementById('clear');
    clearBtn.addEventListener('click', () => window.sim.clear());

})();
</script>
